final_probe_sources.profile.gd:
extends SceneTree
const Fixture=preload("res://tests/support/native_runtime_fixture.gd")
const Profiled=preload("res://.dbg/native-bottleneck/profiled_simulation.gd")
const Backend=preload("res://scripts/core/native_compute.gd")
const Import=preload("res://scripts/atlas/military_import.gd")
const Dir="res://.dbg/native-runtime"
var report: Dictionary={"scope":"diagnostic inclusive timings, not a replacement for the paired benchmark", "stages":[], "every_daily_raw_bytes_exact":true}
func _initialize() -> void:
	call_deferred("run")
func fail(message:String) -> void:
	printerr("BOTTLENECK_FAIL ",message)
	quit(1)
func merge(dest:Dictionary,src:Dictionary) -> void:
	for key in src:dest[key]=int(dest.get(key,0))+int(src[key])
func run() -> void:
	Backend.set_backend_for_tests("native")
	if not Backend.require_native():return
	var manifest: Dictionary=JSON.parse_string(FileAccess.get_file_as_string(Dir+"/manifest.json"))
	var final_proof: Dictionary=JSON.parse_string(FileAccess.get_file_as_string("res://docs/native_runtime_compute_evidence/compute-five-pairs.json"))
	report.source_sha256=Import.source_fingerprint()
	report.fixture_origin_source_sha256=manifest.source_sha256
	var same_fixture: bool=true
	for key in final_proof.fixture:
		if manifest.get(key)!=final_proof.fixture[key]:same_fixture=false
	if report.source_sha256!=final_proof.environment.current_source_sha256 or not same_fixture:
		fail("source or fixture differs from final benchmark")
		return
	report.engine=Engine.get_version_info()
	report.cpu=OS.get_processor_name()
	report.mask=manifest.settlement_mask
	report.world_seed=manifest.world_seed
	report.initial_nations=manifest.initial_nations
	if not bool(manifest.settlement_mask.enabled) or int(manifest.initial_nations)!=40 or int(manifest.world_seed)!=1:
		fail("wrong fixture")
		return
	for stage in [600]:
		var path:=Dir+"/day-%d.bin"%stage
		var descriptor:Dictionary=manifest.stages[str(stage)]
		if Fixture.hash_bytes(FileAccess.get_file_as_bytes(path))!=descriptor.file_sha256:
			fail("file hash differs")
			return
		var payload: Dictionary=FileAccess.open(path,FileAccess.READ).get_var(false)
		var codec_a=Fixture.new()
		var codec_b=Fixture.new()
		var plain_state:GameState=codec_a.unpack(payload.duplicate(true))
		var traced_state:GameState=codec_b.unpack(payload.duplicate(true))
		if Fixture.hash_bytes(var_to_bytes(Fixture.snapshot(plain_state)))!=descriptor.state_sha256:
			fail("restored input differs")
			return
		var plain=Simulation.new()
		var traced=Profiled.new()
		root.add_child(plain)
		root.add_child(traced)
		plain.setup(plain_state)
		traced.setup(traced_state)
		plain.paused=true
		traced.paused=true
		plain.tick_phase_profiling_enabled=true
		traced.tick_phase_profiling_enabled=true
		traced.ai_snapshot_substage_profiling_enabled=true
		if var_to_bytes(Fixture.snapshot(plain_state))!=var_to_bytes(Fixture.snapshot(traced_state)):
			fail("setup differs")
			return
		var phase:Dictionary={}
		var daily:Array=[]
		var facts:Array=[]
		for step in range(30):
			var started:=Time.get_ticks_usec()
			plain._advance_day()
			var plain_usec:=Time.get_ticks_usec()-started
			started=Time.get_ticks_usec()
			traced._advance_day()
			var traced_usec:=Time.get_ticks_usec()-started
			if var_to_bytes(Fixture.snapshot(plain_state))!=var_to_bytes(Fixture.snapshot(traced_state)):
				fail("raw daily differs stage=%d day=%d"%[stage,traced_state.day])
				return
			merge(phase,traced.tick_profile_last_usec)
			daily.append({"day":traced_state.day,"plain_usec":plain_usec,"traced_usec":traced_usec,"phase_usec":traced.tick_profile_last_usec.duplicate()})
			facts.append({"day":traced_state.day,"armies":traced_state.armies.size(),"nations":traced_state.nations.size(),"campaign_fronts":traced_state.campaign_fronts.size(),"campaign_pairs":traced_state.campaign_pairs.size(),"battles":traced_state.battles.size()})
		var row={"start_day":stage,"input_sha256":descriptor.state_sha256,"output_sha256":Fixture.hash_bytes(var_to_bytes(Fixture.snapshot(traced_state))),"phase_total_usec":phase,"inclusive_function_timings":traced.probe_rows,"daily":daily,"facts":facts}
		report.stages.append(row)
		print("BOTTLENECK_STAGE_PASS ",stage)
		plain.queue_free()
		traced.queue_free()
		await process_frame
	report.source_unchanged=Import.source_fingerprint()==report.source_sha256
	if not report.source_unchanged:
		fail("source changed")
		return
	var output="res://.dbg/native-bottleneck/profile-%d.json"%OS.get_process_id()
	FileAccess.open(output,FileAccess.WRITE).store_string(JSON.stringify(report,"  "))
	print("BOTTLENECK_PASS ",ProjectSettings.globalize_path(output))
	quit(0)

