var probe_rows: Dictionary = {}
func record_probe(key: String, started: int) -> void:
	var elapsed := Time.get_ticks_usec()-started
	if not probe_rows.has(key): probe_rows[key]={"calls":0,"total_usec":0,"peak_usec":0}
	var row: Dictionary=probe_rows[key]
	row.calls+=1
	row.total_usec+=elapsed
	row.peak_usec=maxi(row.peak_usec,elapsed)

